export interface SectionConfig {
  id: string;
  name: string;
  questionCount: number;
  color: string;
}

export interface Question {
  id: string;
  number: number;
  sectionId: string; // Changed from section union to sectionId string
  category: string;
  correctAnswer: string;
  points: number;
}

export interface StudentInput {
  name: string;
  answers: Record<string, string>;
}

export interface CategoryResult {
  category: string;
  totalQuestions: number;
  correctCount: number;
  percentage: number;
  sectionName: string;
}

export interface EvaluationResult {
  studentName: string;
  totalScore: number;
  scoreBySection: Record<string, number>;
  categoryResults: CategoryResult[];
  isCorrect: Record<string, boolean>;
}

import React, { useState } from 'react';
import { Question, SectionConfig } from '../types';

interface Props {
  sections: SectionConfig[];
  setSections: (sections: SectionConfig[]) => void;
  questions: Question[];
  setQuestions: (qs: Question[]) => void;
  onNext: () => void;
}

const QuestionSetup: React.FC<Props> = ({ sections, setSections, questions, setQuestions, onNext }) => {
  const [bulkText, setBulkText] = useState<Record<string, string>>({});
  const [showBulk, setShowBulk] = useState<Record<string, boolean>>({});

  const updateSectionName = (id: string, name: string) => {
    setSections(sections.map(s => s.id === id ? { ...s, name } : s));
  };

  const updateQuestionCount = (id: string, count: number) => {
    const newCount = Math.max(0, count);
    const section = sections.find(s => s.id === id);
    if (!section) return;

    // Update section config
    setSections(sections.map(s => s.id === id ? { ...s, questionCount: newCount } : s));

    // Update questions array
    const currentSectionQs = questions.filter(q => q.sectionId === id);
    let updatedQuestions = questions.filter(q => q.sectionId !== id);

    if (currentSectionQs.length < newCount) {
      // Add more
      const toAdd: Question[] = [];
      for (let i = currentSectionQs.length + 1; i <= newCount; i++) {
        toAdd.push({
          id: `${id}-${i}-${Date.now()}`,
          number: i,
          sectionId: id,
          category: '일반',
          correctAnswer: '',
          points: 1.0,
        });
      }
      updatedQuestions = [...updatedQuestions, ...currentSectionQs, ...toAdd];
    } else {
      // Truncate
      updatedQuestions = [...updatedQuestions, ...currentSectionQs.slice(0, newCount)];
    }

    setQuestions(updatedQuestions.sort((a, b) => {
        if (a.sectionId !== b.sectionId) return 0;
        return a.number - b.number;
    }));
  };

  const addSection = () => {
    const newId = `sec-${Date.now()}`;
    const colors = ['from-blue-500 to-indigo-600', 'from-emerald-500 to-teal-600', 'from-rose-500 to-pink-600', 'from-amber-500 to-orange-600', 'from-violet-500 to-purple-600'];
    const color = colors[sections.length % colors.length];

    setSections([...sections, { id: newId, name: `Section ${sections.length + 1}`, questionCount: 10, color }]);

    // Add initial questions for this section
    const newQs: Question[] = Array.from({ length: 10 }, (_, i) => ({
      id: `${newId}-${i + 1}`,
      number: i + 1,
      sectionId: newId,
      category: '일반',
      correctAnswer: '',
      points: 1.0,
    }));
    setQuestions([...questions, ...newQs]);
  };

  const removeSection = (id: string) => {
    setSections(sections.filter(s => s.id !== id));
    setQuestions(questions.filter(q => q.sectionId !== id));
  };

  const updateQuestion = (id: string, field: keyof Question, value: string | number) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, [field]: value } : q));
  };

  const handleBulkPaste = (sectionId: string) => {
    const lines = (bulkText[sectionId] || '').trim().split('\n');
    const newQuestions = [...questions];

    lines.forEach((line, index) => {
      const columns = line.split(/\t|,/);
      const targetQuestion = newQuestions.find(q => q.sectionId === sectionId && q.number === index + 1);

      if (targetQuestion) {
        if (columns[0] !== undefined) targetQuestion.category = columns[0].trim();
        if (columns[1] !== undefined) targetQuestion.correctAnswer = columns[1].trim();
        if (columns[2] !== undefined) targetQuestion.points = parseFloat(columns[2]) || 0;
      }
    });

    setQuestions(newQuestions);
    setShowBulk({ ...showBulk, [sectionId]: false });
    setBulkText({ ...bulkText, [sectionId]: '' });
  };

  const renderSectionTable = (section: SectionConfig) => {
    const sectionQs = questions.filter(q => q.sectionId === section.id).sort((a, b) => a.number - b.number);

    return (
      <div key={section.id} className="mb-10 bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <div className={`px-6 py-4 border-b border-slate-100 flex flex-wrap justify-between items-center bg-gradient-to-r ${section.color} text-white gap-4`}>
          <div className="flex items-center gap-4 flex-1">
            <input 
              type="text" 
              value={section.name} 
              onChange={(e) => updateSectionName(section.id, e.target.value)}
              className="bg-transparent border-b border-white/30 font-bold text-xl focus:outline-none focus:border-white w-full max-w-[200px]"
            />
            <div className="flex items-center gap-2 bg-black/10 px-3 py-1 rounded-lg">
              <span className="text-xs opacity-70">문항 수:</span>
              <input 
                type="number" 
                value={section.questionCount}
                onChange={(e) => updateQuestionCount(section.id, parseInt(e.target.value) || 0)}
                className="bg-transparent w-12 text-center font-bold focus:outline-none"
              />
            </div>
          </div>
          <div className="flex gap-2">
            <button 
              onClick={() => setShowBulk({ ...showBulk, [section.id]: !showBulk[section.id] })}
              className="bg-white/20 hover:bg-white/30 px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-2"
            >
              <i className="fas fa-paste"></i> 엑셀 붙여넣기
            </button>
            <button 
              onClick={() => removeSection(section.id)}
              className="bg-red-500/20 hover:bg-red-500/40 px-3 py-1.5 rounded-lg text-xs font-bold transition-all"
              title="섹션 삭제"
            >
              <i className="fas fa-trash"></i>
            </button>
          </div>
        </div>

        {showBulk[section.id] && (
          <div className="p-6 bg-slate-50 border-b border-slate-200">
            <label className="block text-sm font-bold text-slate-700 mb-2">
              엑셀/스프레드시트에서 [영역, 정답, 배점] 3개 열을 복사하여 아래에 붙여넣으세요.
            </label>
            <textarea 
              value={bulkText[section.id] || ''}
              onChange={(e) => setBulkText({ ...bulkText, [section.id]: e.target.value })}
              className="w-full h-32 p-3 border border-slate-300 rounded-xl text-sm font-mono focus:ring-2 focus:ring-indigo-500/20 mb-3"
              placeholder="영역	정답	배점&#10;어휘	1	1.5&#10;문법	3	1.2"
            />
            <div className="flex justify-end gap-2">
              <button 
                onClick={() => setShowBulk({ ...showBulk, [section.id]: false })}
                className="px-4 py-2 text-sm font-bold text-slate-500 hover:text-slate-800 transition-colors"
              >
                취소
              </button>
              <button 
                onClick={() => handleBulkPaste(section.id)}
                className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-700 transition-all shadow-md"
              >
                데이터 적용하기
              </button>
            </div>
          </div>
        )}

        <div className="overflow-x-auto max-h-[400px]">
          <table className="w-full text-left">
            <thead className="sticky top-0 z-10">
              <tr className="border-b border-slate-100 bg-slate-50 text-slate-600 text-xs uppercase tracking-wider">
                <th className="px-4 py-3 font-semibold w-16">번호</th>
                <th className="px-4 py-3 font-semibold">영역</th>
                <th className="px-4 py-3 font-semibold">정답</th>
                <th className="px-4 py-3 font-semibold w-28">배점</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {sectionQs.map((q) => (
                <tr key={q.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-4 py-3 font-bold text-slate-700">{q.number}</td>
                  <td className="px-4 py-3">
                    <input 
                      type="text" 
                      value={q.category}
                      onChange={(e) => updateQuestion(q.id, 'category', e.target.value)}
                      placeholder="영역"
                      className="w-full border border-slate-200 rounded-md px-3 py-1.5 text-sm focus:ring-2 focus:ring-indigo-500/20"
                    />
                  </td>
                  <td className="px-4 py-3">
                    <input 
                      type="text" 
                      value={q.correctAnswer}
                      onChange={(e) => updateQuestion(q.id, 'correctAnswer', e.target.value)}
                      placeholder="정답"
                      className="w-full border border-slate-200 rounded-md px-3 py-1.5 text-sm focus:ring-2 focus:ring-indigo-500/20"
                    />
                  </td>
                  <td className="px-4 py-3">
                    <input 
                      type="number" 
                      step="0.01"
                      value={q.points}
                      onChange={(e) => updateQuestion(q.id, 'points', parseFloat(e.target.value) || 0)}
                      className="w-full border border-slate-200 rounded-md px-3 py-1.5 text-sm focus:ring-2 focus:ring-indigo-500/20"
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  return (
    <div className="max-w-4xl mx-auto">
      <div className="mb-8 flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-bold text-slate-800">1. 시험 정보 설정</h2>
          <p className="text-slate-500 mt-1">섹션을 추가하고 각 섹션별 문항 수와 정답을 설정하세요.</p>
        </div>
        <button 
          onClick={addSection}
          className="bg-indigo-50 text-indigo-600 hover:bg-indigo-100 px-4 py-2 rounded-xl font-bold transition-all flex items-center gap-2 border border-indigo-200"
        >
          <i className="fas fa-plus"></i> 섹션 추가
        </button>
      </div>

      <div className="space-y-6">
        {sections.map(section => renderSectionTable(section))}
        {sections.length === 0 && (
          <div className="p-20 text-center border-2 border-dashed border-slate-200 rounded-3xl bg-slate-50">
            <i className="fas fa-layer-group text-4xl text-slate-300 mb-4 block"></i>
            <p className="text-slate-400 font-medium">설정된 섹션이 없습니다. 상단의 '섹션 추가' 버튼을 눌러주세요.</p>
          </div>
        )}
      </div>

      <div className="mt-12 flex justify-end">
        <button 
          onClick={onNext}
          disabled={sections.length === 0}
          className="bg-slate-800 hover:bg-slate-900 disabled:bg-slate-200 text-white px-10 py-4 rounded-2xl font-bold transition-all shadow-lg flex items-center gap-3"
        >
          다음 단계: 학생 답안 입력 <i className="fas fa-chevron-right"></i>
        </button>
      </div>
    </div>
  );
};

export default QuestionSetup;

import React from 'react';
import { Question, StudentInput, SectionConfig } from '../types';

interface Props {
  sections: SectionConfig[];
  questions: Question[];
  studentInput: StudentInput;
  setStudentInput: (input: StudentInput) => void;
  onPrev: () => void;
  onSubmit: () => void;
}

const StudentEntry: React.FC<Props> = ({ sections, questions, studentInput, setStudentInput, onPrev, onSubmit }) => {
  const handleAnswerChange = (qId: string, val: string) => {
    setStudentInput({
      ...studentInput,
      answers: { ...studentInput.answers, [qId]: val }
    });
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const inputs = Array.from(document.querySelectorAll('.navigable-input')) as HTMLInputElement[];
      const index = inputs.indexOf(e.currentTarget);
      if (index > -1 && index < inputs.length - 1) {
        inputs[index + 1].focus();
        inputs[index + 1].select();
      } else if (index === inputs.length - 1) {
        e.currentTarget.blur();
      }
    }
  };

  const renderSectionInputs = (section: SectionConfig) => {
    const sectionQs = questions.filter(q => q.sectionId === section.id).sort((a, b) => a.number - b.number);
    if (sectionQs.length === 0) return null;

    return (
      <div key={section.id} className="mb-10">
        <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
          <div className={`w-2 h-6 rounded-full bg-gradient-to-b ${section.color}`}></div>
          {section.name} 답안
        </h3>
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
          {sectionQs.map((q) => (
            <div key={q.id} className="p-3 bg-white border border-slate-200 rounded-xl focus-within:ring-2 focus-within:ring-indigo-500/20 transition-all shadow-sm">
              <div className="flex justify-between items-center mb-1">
                <span className="text-xs font-bold text-slate-400">#{q.number}</span>
                <span className="text-[10px] text-slate-400 truncate max-w-[60px] font-medium">{q.category}</span>
              </div>
              <input 
                type="text" 
                value={studentInput.answers[q.id] || ''}
                onKeyDown={handleKeyDown}
                onChange={(e) => handleAnswerChange(q.id, e.target.value)}
                placeholder="답"
                className="navigable-input w-full text-center font-bold text-slate-700 outline-none placeholder:font-normal placeholder:opacity-30"
              />
            </div>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-8 max-w-5xl mx-auto">
      <div className="mb-10">
        <h2 className="text-3xl font-bold text-slate-800">2. 학생 답안 입력</h2>
        <p className="text-slate-500 mt-1">학생 정보와 마킹한 답안을 정확히 입력해주세요.</p>
      </div>

      <div className="mb-12 p-8 bg-indigo-50 rounded-2xl border border-indigo-100 flex flex-col md:flex-row md:items-center gap-6">
        <div className="flex-1">
          <label className="block text-indigo-900 font-bold mb-2 text-sm uppercase tracking-wider">학생 이름</label>
          <input 
            type="text" 
            value={studentInput.name}
            onKeyDown={handleKeyDown}
            onChange={(e) => setStudentInput({ ...studentInput, name: e.target.value })}
            placeholder="이름을 입력하세요"
            className="navigable-input w-full border border-indigo-200 rounded-xl px-5 py-3 text-lg font-medium focus:outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 bg-white"
          />
        </div>
        <div className="text-slate-500 text-sm md:w-1/3">
          <i className="fas fa-info-circle mr-1"></i> Enter 키를 누르면 다음 문항으로 빠르게 이동합니다.
        </div>
      </div>

      {sections.map(section => renderSectionInputs(section))}

      <div className="mt-12 flex justify-between items-center pt-8 border-t border-slate-100">
        <button 
          onClick={onPrev}
          className="text-slate-400 hover:text-slate-800 font-bold flex items-center gap-2 transition-colors"
        >
          <i className="fas fa-arrow-left"></i> 설정으로 돌아가기
        </button>
        <button 
          onClick={onSubmit}
          disabled={!studentInput.name}
          className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-200 disabled:text-slate-400 text-white px-10 py-4 rounded-2xl font-bold transition-all shadow-xl shadow-indigo-200 flex items-center gap-3"
        >
          채점 결과 확인 <i className="fas fa-check"></i>
        </button>
      </div>
    </div>
  );
};

export default StudentEntry;

import React, { useEffect, useState, useRef } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, LabelList } from 'recharts';
import { EvaluationResult, Question, StudentInput, SectionConfig } from '../types';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';
import LZString from 'lz-string';

const CustomTooltip = ({ active, payload }: any) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    return (
      <div className="bg-slate-900/95 backdrop-blur-md text-white p-4 rounded-2xl shadow-2xl border border-white/10 max-w-[280px]">
        <div className="flex justify-between items-start gap-4 mb-2">
          <p className="font-bold text-indigo-300 text-sm leading-tight">{data.category}</p>
          <p className="text-xs font-black bg-indigo-500 px-2 py-0.5 rounded-lg">{Math.round(data.percentage)}%</p>
        </div>
        <p className="text-[11px] leading-relaxed text-slate-300 font-medium">
          {data.sectionName} 영역의 성취도입니다.
        </p>
      </div>
    );
  }
  return null;
};

interface Props {
  sections: SectionConfig[];
  questions: Question[];
  studentInput: StudentInput;
  onReset: () => void;
  isShared?: boolean;
}

const ReportView: React.FC<Props> = ({ sections, questions, studentInput, onReset, isShared }) => {
  const [result, setResult] = useState<EvaluationResult | null>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
  const [isMobile, setIsMobile] = useState(typeof window !== 'undefined' ? window.innerWidth < 768 : false);
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    calculateResults();
    return () => window.removeEventListener('resize', handleResize);
  }, [questions, studentInput, sections]);

  const calculateResults = async () => {
    const isCorrect: Record<string, boolean> = {};
    const scoreBySection: Record<string, number> = {};
    const categoriesMap: Record<string, { total: number; correct: number; sectionName: string }> = {};

    sections.forEach(s => scoreBySection[s.id] = 0);

    questions.forEach(q => {
      const studentAns = (studentInput.answers[q.id] || '').trim().toLowerCase();
      const correctAns = (q.correctAnswer || '').trim().toLowerCase();
      const correct = studentAns !== '' && studentAns === correctAns;

      isCorrect[q.id] = correct;
      if (correct) {
        scoreBySection[q.sectionId] = (scoreBySection[q.sectionId] || 0) + q.points;
      }

      const section = sections.find(s => s.id === q.sectionId);
      const sectionName = section?.name || '기타';
      const fullCategoryKey = `${q.sectionId}-${q.category}`;

      if (!categoriesMap[fullCategoryKey]) {
        categoriesMap[fullCategoryKey] = { total: 0, correct: 0, sectionName };
      }
      categoriesMap[fullCategoryKey].total += 1;
      if (correct) categoriesMap[fullCategoryKey].correct += 1;
    });

    const categoryResults = Object.keys(categoriesMap).map(key => {
      const entry = categoriesMap[key];
      const catName = key.split('-').slice(1).join('-');
      return {
        category: catName,
        sectionName: entry.sectionName,
        totalQuestions: entry.total,
        correctCount: entry.correct,
        percentage: (entry.correct / entry.total) * 100
      };
    });

    const totalScore = Object.values(scoreBySection).reduce((acc, val) => acc + val, 0);

    const finalResult: EvaluationResult = {
      studentName: studentInput.name,
      totalScore: Math.round(totalScore * 100) / 100,
      scoreBySection,
      categoryResults,
      isCorrect
    };

    setResult(finalResult);
  };

  const copyShareLink = () => {
    try {
      // Basic sharing logic - we need to pack sections and question config
      const sectionsStr = sections.map(s => `${s.name}*${s.questionCount}*${s.color}`).join('^');
      const questionsStr = questions.map(q => `${q.sectionId}*${q.category}*${q.correctAnswer}*${q.points}`).join('^');
      const answersStr = questions.map(q => studentInput.answers[q.id] || "").join('^');

      const pack = [
        studentInput.name,
        sectionsStr,
        questionsStr,
        answersStr
      ].join('|');

      const compressed = LZString.compressToEncodedURIComponent(pack);
      const url = `${window.location.origin}${window.location.pathname}#v4=${compressed}`;

      navigator.clipboard.writeText(url).then(() => alert("성적표 공유 링크가 복사되었습니다."));
    } catch (err) {
      alert("링크 생성 실패");
    }
  };

  const downloadPdf = async () => {
    if (!reportRef.current) return;
    setIsGeneratingPdf(true);
    try {
      const canvas = await html2canvas(reportRef.current, { scale: 2, useCORS: true, backgroundColor: '#f8fafc' });
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgData = canvas.toDataURL('image/png');
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`${studentInput.name}_성적표.pdf`);
    } catch (e) {
      alert("PDF 생성 오류");
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  if (!result) return <div className="p-20 text-center font-bold text-slate-400">데이터를 불러오는 중입니다...</div>;

  return (
    <div className="max-w-6xl mx-auto space-y-6 pb-20">
      <div className="flex flex-wrap justify-end gap-3 no-print px-4 md:px-0">
        {!isShared && (
          <button onClick={copyShareLink} className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-white text-slate-700 border border-slate-200 hover:bg-slate-50 px-5 py-3 rounded-xl font-bold transition-all shadow-sm active:scale-95">
            <i className="fas fa-share-nodes text-indigo-500"></i> 공유 링크 복사
          </button>
        )}
        <button onClick={downloadPdf} disabled={isGeneratingPdf} className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-indigo-600 text-white hover:bg-indigo-700 px-5 py-3 rounded-xl font-bold transition-all shadow-md active:scale-95 disabled:opacity-50">
          {isGeneratingPdf ? <i className="fas fa-spinner animate-spin"></i> : <><i className="fas fa-file-pdf"></i> PDF 저장하기</>}
        </button>
      </div>

      <div ref={reportRef} className="space-y-6 p-4 md:p-0">
        <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-[2.5rem] p-8 md:p-10 text-white shadow-xl relative overflow-hidden border border-slate-700">
          <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-20 -mt-20 blur-3xl"></div>
          <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-8">
            <div className="text-center md:text-left">
