import React, { useState, useEffect } from 'react';
import { Question, StudentInput, SectionConfig } from './types';
import QuestionSetup from './components/QuestionSetup';
import StudentEntry from './components/StudentEntry';
import ReportView from './components/ReportView';
import LZString from 'lz-string';

enum Step {
  SETUP,
  INPUT,
  REPORT
}

const initialSections: SectionConfig[] = [
  { id: 'sec-1', name: '영역 1', questionCount: 10, color: 'from-blue-500 to-indigo-600' },
  { id: 'sec-2', name: '영역 2', questionCount: 10, color: 'from-emerald-500 to-teal-600' }
];

const generateInitialQuestions = (secs: SectionConfig[]): Question[] => {
  const allQs: Question[] = [];
  secs.forEach(s => {
    for (let i = 1; i <= s.questionCount; i++) {
      allQs.push({
        id: `${s.id}-${i}`,
        number: i,
        sectionId: s.id,
        category: '일반',
        correctAnswer: '',
        points: 1.0,
      });
    }
  });
  return allQs;
};

const App: React.FC = () => {
  const [isSharedMode, setIsSharedMode] = useState(() => {
    if (typeof window !== 'undefined') {
      return window.location.hash.startsWith('#v4=');
    }
    return false;
  });

  const [currentStep, setCurrentStep] = useState<Step>(isSharedMode ? Step.REPORT : Step.SETUP);
  const [sections, setSections] = useState<SectionConfig[]>(initialSections);
  const [questions, setQuestions] = useState<Question[]>(generateInitialQuestions(initialSections));
  const [studentInput, setStudentInput] = useState<StudentInput>({
    name: '',
    answers: {}
  });

  useEffect(() => {
    const checkHash = () => {
      const hash = window.location.hash;
      if (!hash || !hash.startsWith('#v4=')) return;

      try {
        const compressed = hash.replace('#v4=', '');
        const decompressed = LZString.decompressFromEncodedURIComponent(compressed);
        if (!decompressed) return;

        const [name, sectionsStr, questionsStr, answersStr] = decompressed.split('|');

        const restoredSections: SectionConfig[] = sectionsStr.split('^').map((s, i) => {
          const [sName, sCount, sColor] = s.split('*');
          return { id: `sec-shared-${i}`, name: sName, questionCount: Number(sCount), color: sColor };
        });

        const rawQData = questionsStr.split('^');
        let qPointer = 0;
        const finalQs: Question[] = [];
        const finalAnswers: Record<string, string> = {};
        const ansArray = answersStr.split('^');

        restoredSections.forEach(rs => {
           for(let k=1; k<=rs.questionCount; k++) {
              if (rawQData[qPointer]) {
                const [_, cat, correct, pts] = rawQData[qPointer].split('*');
                const qId = `qs-${rs.id}-${k}`;
                finalQs.push({
                   id: qId,
                   number: k,
                   sectionId: rs.id,
                   category: cat,
                   correctAnswer: correct,
                   points: Number(pts)
                });
                finalAnswers[qId] = ansArray[qPointer] || "";
              }
              qPointer++;
           }
        });

        setSections(restoredSections);
        setQuestions(finalQs);
        setStudentInput({ name, answers: finalAnswers });
        setIsSharedMode(true);
        setCurrentStep(Step.REPORT);
      } catch (e) {
        console.error("Link Error", e);
      }
    };

    checkHash();
    window.addEventListener('hashchange', checkHash);
    return () => window.removeEventListener('hashchange', checkHash);
  }, []);

  const handleReset = () => {
    if (isSharedMode) {
      window.location.hash = '';
      window.location.reload(); 
    } else {
      setStudentInput({ name: '', answers: {} });
      setCurrentStep(Step.INPUT);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50/50">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 no-print">
        <div className="max-w-6xl mx-auto px-6 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-200">
              <i className="fas fa-graduation-cap text-lg"></i>
            </div>
            <div>
              <h1 className="font-bold text-slate-800 text-lg leading-tight">스마트 성적표</h1>
              <p className="text-[10px] text-slate-400 font-semibold tracking-widest uppercase">Report Builder Pro</p>
            </div>
          </div>

          {!isSharedMode && (
            <nav className="hidden md:flex items-center gap-1 bg-slate-100 p-1 rounded-xl">
              {[
                { id: Step.SETUP, label: '정보 설정', icon: 'fa-cog' },
                { id: Step.INPUT, label: '답안 입력', icon: 'fa-edit' },
                { id: Step.REPORT, label: '결과 리포트', icon: 'fa-chart-pie' }
              ].map((s) => (
                <button
                  key={s.id}
                  disabled={currentStep < s.id}
                  onClick={() => setCurrentStep(s.id)}
                  className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all flex items-center gap-2 ${
                    currentStep === s.id 
                      ? 'bg-white text-indigo-600 shadow-sm' 
                      : 'text-slate-500 hover:text-slate-700'
                  } ${currentStep < s.id ? 'opacity-40 cursor-not-allowed' : ''}`}
                >
                  <i className={`fas ${s.icon}`}></i> {s.label}
                </button>
              ))}
            </nav>
          )}
        </div>
      </header>

      <main className="flex-1 container mx-auto px-6 py-10">
        {!isSharedMode && currentStep === Step.SETUP && (
          <QuestionSetup 
            sections={sections}
            setSections={setSections}
            questions={questions} 
            setQuestions={setQuestions} 
            onNext={() => setCurrentStep(Step.INPUT)} 
          />
        )}
        {!isSharedMode && currentStep === Step.INPUT && (
          <StudentEntry 
            sections={sections}
            questions={questions} 
            studentInput={studentInput} 
            setStudentInput={setStudentInput} 
            onPrev={() => setCurrentStep(Step.SETUP)}
            onSubmit={() => setCurrentStep(Step.REPORT)}
          />
        )}
        {(isSharedMode || currentStep === Step.REPORT) && (
          <ReportView 
            sections={sections}
            questions={questions} 
            studentInput={studentInput} 
            onReset={handleReset}
            isShared={isSharedMode}
          />
        )}
      </main>

      {!isSharedMode && (
        <footer className="bg-slate-50 border-t border-slate-200 py-8 no-print">
          <div className="max-w-6xl mx-auto px-6 text-center">
            <p className="text-slate-400 text-sm">© 2024 Smart Report Card Builder. All rights reserved.</p>
          </div>
        </footer>
      )}
    </div>
  );
};

export default App;

export interface SectionConfig {
  id: string;
  name: string;
  questionCount: number;
  color: string;
}

export interface Question {
  id: string;
  number: number;
  sectionId: string; // Changed from section union to sectionId string
  category: string;
  correctAnswer: string;
  points: number;
}

export interface StudentInput {
  name: string;
  answers: Record<string, string>;
}

export interface CategoryResult {
  category: string;
  totalQuestions: number;
  correctCount: number;
  percentage: number;
  sectionName: string;
}

export interface EvaluationResult {
  studentName: string;
  totalScore: number;
  scoreBySection: Record<string, number>;
  maxScoreBySection: Record<string, number>; // 섹션별 만점 추가
  categoryResults: CategoryResult[];
  isCorrect: Record<string, boolean>;
}

import React, { useEffect, useState, useRef } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, LabelList } from 'recharts';
import { EvaluationResult, Question, StudentInput, SectionConfig } from '../types';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';
import LZString from 'lz-string';

const CustomTooltip = ({ active, payload }: any) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    return (
      <div className="bg-slate-900/95 backdrop-blur-md text-white p-3 rounded-xl shadow-2xl border border-white/10">
        <div className="flex justify-between items-center gap-4">
          <p className="font-bold text-indigo-300 text-sm">{data.category}</p>
          <p className="text-xs font-black bg-indigo-500 px-2 py-0.5 rounded-lg">{Math.round(data.percentage)}%</p>
        </div>
      </div>
    );
  }
  return null;
};

interface Props {
  sections: SectionConfig[];
  questions: Question[];
  studentInput: StudentInput;
  onReset: () => void;
  isShared?: boolean;
}

const ReportView: React.FC<Props> = ({ sections, questions, studentInput, onReset, isShared }) => {
  const [result, setResult] = useState<EvaluationResult | null>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
  const [isMobile, setIsMobile] = useState(typeof window !== 'undefined' ? window.innerWidth < 768 : false);
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    calculateResults();
    return () => window.removeEventListener('resize', handleResize);
  }, [questions, studentInput, sections]);

  const calculateResults = async () => {
    const isCorrect: Record<string, boolean> = {};
    const scoreBySection: Record<string, number> = {};
    const maxScoreBySection: Record<string, number> = {};
    const categoriesMap: Record<string, { category: string; total: number; correct: number; sectionName: string }> = {};

    sections.forEach(s => {
      scoreBySection[s.id] = 0;
      maxScoreBySection[s.id] = 0;
    });

    questions.forEach(q => {
      const studentAns = (studentInput.answers[q.id] || '').trim().toLowerCase();
      const correctAns = (q.correctAnswer || '').trim().toLowerCase();
      const correct = studentAns !== '' && studentAns === correctAns;

      isCorrect[q.id] = correct;

      // 만점 계산 (모든 문항의 배점 합계)
      maxScoreBySection[q.sectionId] = (maxScoreBySection[q.sectionId] || 0) + q.points;

      // 획득 점수 계산
      if (correct) {
        scoreBySection[q.sectionId] = (scoreBySection[q.sectionId] || 0) + q.points;
      }

      const section = sections.find(s => s.id === q.sectionId);
      const sectionName = section?.name || '기타';
      const mapKey = `${q.sectionId}_${q.category}`;

      if (!categoriesMap[mapKey]) {
        categoriesMap[mapKey] = { category: q.category, total: 0, correct: 0, sectionName };
      }
      categoriesMap[mapKey].total += 1;
      if (correct) categoriesMap[mapKey].correct += 1;
    });

    const categoryResults = Object.values(categoriesMap).map(entry => ({
      category: entry.category,
      sectionName: entry.sectionName,
      totalQuestions: entry.total,
      correctCount: entry.correct,
      percentage: (entry.correct / entry.total) * 100
    }));

    const totalScore = Object.values(scoreBySection).reduce((acc, val) => acc + val, 0);

    const finalResult: EvaluationResult = {
      studentName: studentInput.name,
      totalScore: Math.round(totalScore * 100) / 100,
      scoreBySection,
      maxScoreBySection,
      categoryResults,
      isCorrect
    };

    setResult(finalResult);
  };

  const copyShareLink = () => {
    try {
      const sectionsStr = sections.map(s => `${s.name}*${s.questionCount}*${s.color}`).join('^');
      const questionsStr = questions.map(q => `${q.sectionId}*${q.category}*${q.correctAnswer}*${q.points}`).join('^');
      const answersStr = questions.map(q => studentInput.answers[q.id] || "").join('^');

      const pack = [
        studentInput.name,
        sectionsStr,
        questionsStr,
        answersStr
      ].join('|');

      const compressed = LZString.compressToEncodedURIComponent(pack);
      const url = `${window.location.origin}${window.location.pathname}#v4=${compressed}`;

      navigator.clipboard.writeText(url).then(() => alert("성적표 공유 링크가 복사되었습니다."));
    } catch (err) {
      alert("링크 생성 실패");
    }
  };

  const downloadPdf = async () => {
    if (!reportRef.current) return;
    setIsGeneratingPdf(true);
    try {
      const canvas = await html2canvas(reportRef.current, { scale: 2, useCORS: true, backgroundColor: '#f8fafc' });
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgData = canvas.toDataURL('image/png');
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`${studentInput.name}_성적표.pdf`);
    } catch (e) {
      alert("PDF 생성 오류");
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  if (!result) return <div className="p-20 text-center font-bold text-slate-400">데이터를 불러오는 중입니다...</div>;

  // 전체 만점 계산
  const grandMaxScore = Object.values(result.maxScoreBySection).reduce((a, b) => a + b, 0);

  return (
    <div className="max-w-6xl mx-auto space-y-6 pb-20">
      <div className="flex flex-wrap justify-end gap-3 no-print px-4 md:px-0">
        {!isShared && (
          <button onClick={copyShareLink} className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-white text-slate-700 border border-slate-200 hover:bg-slate-50 px-5 py-3 rounded-xl font-bold transition-all shadow-sm active:scale-95">
            <i className="fas fa-share-nodes text-indigo-500"></i> 공유 링크 복사
          </button>
        )}
        <button onClick={downloadPdf} disabled={isGeneratingPdf} className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-indigo-600 text-white hover:bg-indigo-700 px-5 py-3 rounded-xl font-bold transition-all shadow-md active:scale-95 disabled:opacity-50">
          {isGeneratingPdf ? <i className="fas fa-spinner animate-spin"></i> : <><i className="fas fa-file-pdf"></i> PDF 저장하기</>}
        </button>
      </div>

      <div ref={reportRef} className="space-y-6 p-4 md:p-0">
        <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-[2.5rem] p-8 md:p-10 text-white shadow-xl relative overflow-hidden border border-slate-700">
          <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-20 -mt-20 blur-3xl"></div>
          <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-8">
            <div className="text-center md:text-left">
              <span className="inline-block bg-indigo-500/20 backdrop-blur-md px-4 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider mb-4 border border-indigo-500/30">Official Student Report</span>
              <h2 className="text-4xl font-black">{result.studentName} 학생</h2>
              <div className="mt-6 flex flex-wrap gap-4 justify-center md:justify-start">
                {sections.map(s => (
                  <div key={s.id} className="bg-white/5 px-4 py-3 rounded-2xl border border-white/10 min-w-[120px] backdrop-blur-sm transition-all hover:bg-white/10">
                    <span className="text-[10px] uppercase font-bold text-indigo-300 block mb-1">{s.name}</span>
                    <div className="flex items-baseline gap-1">
                      <span className="text-2xl font-black">{Math.round((result.scoreBySection[s.id] || 0) * 10) / 10}</span>
                      <span className="text-xs font-bold opacity-40">/ {Math.round((result.maxScoreBySection[s.id] || 0) * 10) / 10}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
            <div className="bg-white text-slate-900 rounded-[2.5rem] p-8 text-center shadow-2xl min-w-[240px] border border-white/20">
              <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Grand Total Score</span>
              <div className="text-6xl font-black text-indigo-600 mt-2 tracking-tighter">
                {result.totalScore}
              </div>
              <div className="mt-2 text-slate-400 font-bold text-sm">
                out of {grandMaxScore} points
              </div>
              <div className="mt-4 h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-indigo-500 rounded-full" 
                  style={{ width: `${(result.totalScore / grandMaxScore) * 100}%` }}
                ></div>
              </div>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {sections.map((section) => {
            const sectionData = result.categoryResults.filter(r => r.sectionName === section.name);
            return (
              <div key={section.id} className="bg-white rounded-[2rem] p-6 border border-slate-200 shadow-sm">
                <div className="flex justify-between items-start mb-6">
                  <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2 uppercase tracking-tight">
                    <div className={`w-1.5 h-5 rounded-full bg-gradient-to-b ${section.color}`}></div>
                    {section.name}
                  </h3>
                  <div className="text-xs font-bold text-slate-400 bg-slate-50 px-3 py-1 rounded-full">
                    {Math.round((result.scoreBySection[section.id] || 0) * 10) / 10} / {Math.round((result.maxScoreBySection[section.id] || 0) * 10) / 10}
                  </div>
                </div>
                <div className="h-[250px] w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={sectionData} layout={isMobile ? "horizontal" : "vertical"} margin={{ left: isMobile ? 0 : 20, right: 30 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" horizontal={!isMobile} vertical={isMobile} />
                      <XAxis type={isMobile ? "category" : "number"} dataKey={isMobile ? "category" : undefined} hide={!isMobile} />
                      <YAxis type={isMobile ? "number" : "category"} dataKey={isMobile ? undefined : "category"} hide={isMobile} width={80} tick={{ fontSize: 11, fontWeight: 700, fill: '#64748b' }} />
                      <Tooltip content={<CustomTooltip />} cursor={{ fill: '#f1f5f9', opacity: 0.4 }} />
                      <Bar dataKey="percentage" radius={isMobile ? [6, 6, 0, 0] : [0, 6, 6, 0]} barSize={20}>
                        {sectionData.map((entry: any, i: number) => (
                          <Cell key={`cell-${i}`} fill={entry.percentage >= 80 ? '#10b981' : entry.percentage >= 50 ? '#6366f1' : '#f43f5e'} />
                        ))}
                        <LabelList dataKey="percentage" position={isMobile ? "top" : "right"} formatter={(v: number) => `${Math.round(v)}%`} style={{ fontSize: '10px', fontWeight: 'bold', fill: '#94a3b8' }} />
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {!isShared && (
        <div className="flex justify-center pt-8 no-print px-4">
          <button onClick={onReset} className="w-full md:w-auto bg-slate-900 text-white px-12 py-4 rounded-2xl font-bold shadow-xl active:scale-95 transition-transform">
            처음으로 돌아가기
          </button>
        </div>
      )}
    </div>
  );
};

